// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address caller) public {
        // Ensure caller is the owner when calling setOwner (onlyOwner modifier requires it)
        vm.assume(caller == c.owner());
        // Optionally restrict _owner to avoid overflow/other issues (not needed here)
        vm.prank(caller);
        (bool success) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        assertTrue(success && c.owner() == _owner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        address originalOwner = c.owner();
        c.setOwner(_owner);
        c.setOwner(originalOwner);
        assertTrue(c.owner() == originalOwner);
    }
}

